-- person directory extract
SELECT DISTINCT *, p.*, p.record_id, p.first_name AS given_name, p.last_name, p.first_name || ' ' || p.last_name AS full_name, ARRAY[p.record_id::text], p.notes->'city'->>'name', p.age, p.eye_color, p.email, p.phone_number, public.person.status, count(*) FILTER (WHERE p.age > 17), true AS is_active, false AS is_cycle, coalesce(o.job_title, 'none') AS title, CASE /* age band */ WHEN p.age < 18 THEN 'minor' WHEN p.age >= 65 THEN 'senior' ELSE 'adult' END AS age_group, a.city, a.province, a.country, a.postal_code, o.department, o.salary, CAST(o.salary AS numeric), o.salary::numeric(10, 2), o.salary * 1.1 AS raised, (SELECT max(salary) FROM occupation) AS cap FROM public.person AS p INNER JOIN public.address AS a ON p.address_id = a.address_id LEFT JOIN occupation AS o ON p.occupation_id = o.occupation_id RIGHT OUTER JOIN department AS d ON o.department_id = d.department_id FULL JOIN region AS r ON a.region_id = r.region_id JOIN country AS c ON a.country_id = c.country_id CROSS JOIN calendar AS cal NATURAL LEFT JOIN status_flag NATURAL JOIN audit INNER JOIN extra USING (record_id, tenant_id) JOIN (SELECT record_id FROM watchlist) AS w ON p.record_id = w.record_id WHERE p.record_id != 0 AND p.age BETWEEN 18 AND 65 AND p.age NOT BETWEEN 0 AND 1 AND p.eye_color IN ('blue', 'green', 'hazel', 'brown') AND p.status = 'active' AND p.last_name LIKE 'S%' AND p.email NOT LIKE '%test%' AND a.country = 'Canada' AND p.age > 17 AND p.age >= 18 AND p.age < 66 AND p.age <= 65 AND p.record_id <> 1 AND NOT a.city IS NULL AND (o.salary IS NULL OR o.salary >= 50000) AND o.job_title IS NOT NULL AND p.record_id IN (SELECT record_id FROM watchlist) AND p.record_id NOT IN (SELECT person_id FROM ban) AND EXISTS (SELECT 1 FROM login WHERE login.person_id = p.record_id) AND NOT EXISTS (SELECT 1 FROM ban WHERE ban.person_id = p.record_id) AND o.salary > ALL (SELECT min_salary FROM pay_band) AND o.salary >= ANY (SELECT mid_salary FROM pay_band) AND p.age < SOME (SELECT max_age FROM age_limit) GROUP BY p.record_id, p.first_name, p.last_name, p.age, p.eye_color, p.email, p.phone_number, public.person.status, a.city, a.province, a.country, a.postal_code, o.department, o.salary, o.job_title HAVING count(*) != 0 AND NOT p.age IS NOT NULL UNION ALL SELECT p.record_id, p.first_name, p.last_name FROM public.person AS p WHERE p.status = 'alumni' INTERSECT SELECT p.record_id, p.first_name, p.last_name FROM public.person AS p WHERE p.record_id IN (SELECT person_id FROM alumni) EXCEPT SELECT p.record_id, p.first_name, p.last_name FROM public.person AS p WHERE EXISTS (SELECT 1 FROM suppress WHERE suppress.person_id = p.record_id) ORDER BY p.last_name DESC, p.first_name ASC, p.record_id OFFSET 5 LIMIT 10;
